'use client';

import { useState } from 'react';
import { Card, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Checkbox } from '@/components/ui/checkbox';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Grid, List, X } from 'lucide-react';
import Link from 'next/link';
import Image from 'next/image';
import { useProducts } from '@/hooks/use-products';
import { useLocale } from 'next-intl';
import { Locale } from '@/i18n/config';
import { ProductsFilters } from '@/lib/services/products.service';

const ProductsPage = () => {
  const locale = useLocale() as Locale;
  const [viewMode, setViewMode] = useState<'grid' | 'list'>('grid');
  const [sortBy, setSortBy] = useState<
    'newest' | 'popular' | 'price_low' | 'price_high'
  >('newest');
  const [filters, setFilters] = useState({
    class: [] as string[],
    skills: [] as string[],
    admission: false,
    jobs: false,
    books: false,
    courseType: [] as string[],
    price: [] as string[],
  });
  const [currentPage, setCurrentPage] = useState(1);

  // Build API filters from UI filters
  const apiFilters: ProductsFilters = {
    page: currentPage,
    per_page: 9,
    limit: 9,
    sort_by: sortBy,
    ...(filters.price.includes('Free') && { price_type: 'free' as const }),
    ...(filters.price.includes('Paid') && { price_type: 'paid' as const }),
  };

  const {
    data: productsData,
    isLoading,
    isError,
    error,
  } = useProducts(apiFilters, locale);
  console.log('productsDat', productsData);
  const handleFilterChange = (filterType: string, value: string | boolean) => {
    setFilters((prev) => ({
      ...prev,
      [filterType]:
        typeof value === 'boolean'
          ? value
          : Array.isArray(prev[filterType as keyof typeof prev])
          ? (prev[filterType as keyof typeof prev] as string[]).includes(
              value as string
            )
            ? (prev[filterType as keyof typeof prev] as string[]).filter(
                (item) => item !== value
              )
            : [
                ...(prev[filterType as keyof typeof prev] as string[]),
                value as string,
              ]
          : value,
    }));
    // Reset to first page when filters change
    setCurrentPage(1);
  };

  const clearAllFilters = () => {
    setFilters({
      class: [],
      skills: [],
      admission: false,
      jobs: false,
      books: false,
      courseType: [],
      price: [],
    });
    setCurrentPage(1);
  };

  // Handle loading and error states
  if (isLoading) {
    return (
      <div className="container mx-auto px-4 py-8">
        <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
          <div className="lg:col-span-1">
            <div className="animate-pulse space-y-4">
              <div className="h-6 bg-gray-200 rounded w-20"></div>
              <div className="space-y-2">
                {[...Array(8)].map((_, i) => (
                  <div key={i} className="h-4 bg-gray-200 rounded w-32"></div>
                ))}
              </div>
            </div>
          </div>
          <div className="lg:col-span-3">
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
              {[...Array(6)].map((_, i) => (
                <div key={i} className="animate-pulse">
                  <div className="h-40 bg-gray-200 rounded-lg mb-4"></div>
                  <div className="h-4 bg-gray-200 rounded w-3/4 mb-2"></div>
                  <div className="h-3 bg-gray-200 rounded w-1/2"></div>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
    );
  }

  if (isError) {
    return (
      <div className="container mx-auto px-4 py-8">
        <div className="text-center">
          <h2 className="text-2xl font-bold text-gray-900 mb-4">
            Something went wrong
          </h2>
          <p className="text-gray-600 mb-4">
            {error?.message || 'Failed to load products'}
          </p>
          <Button onClick={() => window.location.reload()}>Try Again</Button>
        </div>
      </div>
    );
  }

  const products = productsData?.data?.products || [];
  const meta = productsData?.data?.pagination_meta;
  const totalResults = meta?.total_items || 0;
  const totalPages = meta?.total_page || 1;

  return (
    <div className="container mx-auto px-4 py-6">
      <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
        {/* Left Sidebar - Filters */}
        <div className="lg:col-span-1">
          <div className="bg-white rounded-lg p-4 shadow-sm border">
            <div className="flex items-center justify-between mb-4">
              <h3 className="font-semibold text-gray-900">Filter by</h3>
              <Button
                variant="ghost"
                size="sm"
                onClick={clearAllFilters}
                className="text-red-500 hover:text-red-700"
              >
                <X className="w-4 h-4 mr-1" />
                Clear all filters
              </Button>
            </div>

            <div className="space-y-6">
              {/* Class Filter */}
              <div>
                <h4 className="font-medium mb-3">Class 1-12</h4>
                <div className="space-y-2">
                  {[
                    'Class 6',
                    'Class 7',
                    'Class 8',
                    'Class 9',
                    'Class 10',
                    'HSC',
                  ].map((item) => (
                    <div key={item} className="flex items-center space-x-2">
                      <Checkbox
                        id={item}
                        checked={filters.class.includes(item)}
                        onCheckedChange={() =>
                          handleFilterChange('class', item)
                        }
                      />
                      <label htmlFor={item} className="text-sm text-gray-700">
                        {item}
                      </label>
                    </div>
                  ))}
                </div>
              </div>

              {/* Skills Filter */}
              <div>
                <h4 className="font-medium mb-3">Skills</h4>
                <div className="space-y-2">
                  <div className="flex items-center space-x-2">
                    <Checkbox
                      id="admission"
                      checked={filters.admission}
                      onCheckedChange={(checked) =>
                        handleFilterChange('admission', checked)
                      }
                    />
                    <label
                      htmlFor="admission"
                      className="text-sm text-gray-700"
                    >
                      Admission
                    </label>
                  </div>
                  <div className="flex items-center space-x-2">
                    <Checkbox
                      id="jobs"
                      checked={filters.jobs}
                      onCheckedChange={(checked) =>
                        handleFilterChange('jobs', checked)
                      }
                    />
                    <label htmlFor="jobs" className="text-sm text-gray-700">
                      Jobs
                    </label>
                  </div>
                  <div className="flex items-center space-x-2">
                    <Checkbox
                      id="books"
                      checked={filters.books}
                      onCheckedChange={(checked) =>
                        handleFilterChange('books', checked)
                      }
                    />
                    <label htmlFor="books" className="text-sm text-gray-700">
                      Books
                    </label>
                  </div>
                </div>
              </div>

              {/* Course Type Filter */}
              <div>
                <h4 className="font-medium mb-3">Course Type</h4>
                <div className="space-y-2">
                  {['Recorded Course', 'Live Course', 'Crash Course'].map(
                    (item) => (
                      <div key={item} className="flex items-center space-x-2">
                        <Checkbox
                          id={item}
                          checked={filters.courseType.includes(item)}
                          onCheckedChange={() =>
                            handleFilterChange('courseType', item)
                          }
                        />
                        <label htmlFor={item} className="text-sm text-gray-700">
                          {item}
                        </label>
                      </div>
                    )
                  )}
                </div>
              </div>

              {/* Price Filter */}
              <div>
                <h4 className="font-medium mb-3">Price</h4>
                <div className="space-y-2">
                  {['Paid', 'Free'].map((item) => (
                    <div key={item} className="flex items-center space-x-2">
                      <Checkbox
                        id={item}
                        checked={filters.price.includes(item)}
                        onCheckedChange={() =>
                          handleFilterChange('price', item)
                        }
                      />
                      <label htmlFor={item} className="text-sm text-gray-700">
                        {item}
                      </label>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* Right Content Area */}
        <div className="lg:col-span-3">
          {/* Header with results count and controls */}
          <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center mb-6 gap-4">
            <div className="text-sm text-gray-600">
              Showing {(currentPage - 1) * (meta?.items_per_page || 12) + 1} -{' '}
              {Math.min(
                currentPage * (meta?.items_per_page || 12),
                totalResults
              )}{' '}
              of {totalResults} results
            </div>
            <div className="flex items-center gap-4">
              <div className="flex items-center gap-2">
                <span className="text-sm text-gray-600">Sort by:</span>
                <Select value={sortBy} onValueChange={setSortBy}>
                  <SelectTrigger className="w-40">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="newest">Newest</SelectItem>
                    <SelectItem value="popular">Most Popular</SelectItem>
                    <SelectItem value="price_low">
                      Price: Low to High
                    </SelectItem>
                    <SelectItem value="price_high">
                      Price: High to Low
                    </SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div className="flex items-center gap-1 border rounded-md">
                <Button
                  variant={viewMode === 'grid' ? 'default' : 'ghost'}
                  size="sm"
                  onClick={() => setViewMode('grid')}
                >
                  <Grid className="w-4 h-4" />
                </Button>
                <Button
                  variant={viewMode === 'list' ? 'default' : 'ghost'}
                  size="sm"
                  onClick={() => setViewMode('list')}
                >
                  <List className="w-4 h-4" />
                </Button>
              </div>
            </div>
          </div>

          {/* Course Grid */}
          <div
            className={`grid gap-4 mb-8 ${
              viewMode === 'grid'
                ? 'grid-cols-1 md:grid-cols-2 lg:grid-cols-3'
                : 'grid-cols-1'
            }`}
          >
            {products.map((product) => {
              const thumbnail = product.media?.find(
                (m) => m.name === 'thumbnail'
              )?.resource_value;
              const isFree = product.price_type === 'free';

              return (
                <Link key={product.id} href={`/product/${product.slug}`}>
                  <Card className="overflow-hidden hover:shadow-lg transition-shadow cursor-pointer h-full">
                    <div className="relative">
                      {thumbnail ? (
                        <div className="relative h-40 w-full">
                          <Image
                            src={thumbnail}
                            alt={product.title}
                            fill
                            className="object-cover"
                            sizes="(max-width: 768px) 100vw, (max-width: 1200px) 50vw, 33vw"
                          />
                        </div>
                      ) : (
                        <div className="h-40 bg-gradient-to-br from-purple-500 to-blue-600 flex items-center justify-center">
                          <div className="text-white text-sm font-semibold text-center px-4 line-clamp-3">
                            {product.title}
                          </div>
                        </div>
                      )}
                      {product.modality === 'book' && (
                        <Badge className="absolute top-2 left-2 bg-blue-500 text-white">
                          Book
                        </Badge>
                      )}
                    </div>
                    <CardContent className="p-4">
                      <h3 className="font-semibold text-foreground mb-2 line-clamp-2 text-sm leading-tight">
                        {product.title}
                      </h3>
                      {product.instructor_text &&
                        product.instructor_text.trim() && (
                          <p className="text-xs text-muted-foreground mb-3 line-clamp-1">
                            {product.instructor_text}
                          </p>
                        )}
                      <div className="flex items-center justify-between mt-auto">
                        <div className="flex-1">
                          {isFree ? (
                            <span className="text-[#1CAB55] font-bold text-sm">
                              Free
                            </span>
                          ) : (
                            <div className="flex items-center gap-1">
                              <div
                                className="text-sm font-semibold text-foreground"
                                dangerouslySetInnerHTML={{
                                  __html: product.price_details.text,
                                }}
                              />
                              {product.price_details.max_price >
                                product.price_details.min_final_price && (
                                <span className="text-xs text-muted-foreground line-through">
                                  ৳{product.price_details.max_price}
                                </span>
                              )}
                            </div>
                          )}
                        </div>
                        <Badge
                          variant="outline"
                          className="text-xs capitalize ml-2 text-muted-foreground"
                        >
                          {product.modality.replace('_', ' ')}
                        </Badge>
                      </div>
                      {product.is_enrolled && (
                        <div className="mt-2 text-xs text-blue-600 font-medium">
                          ✓ Enrolled
                        </div>
                      )}
                    </CardContent>
                  </Card>
                </Link>
              );
            })}
          </div>

          {/* Pagination */}
          {totalPages > 1 && (
            <div className="flex justify-center items-center gap-2">
              <Button
                variant="outline"
                size="sm"
                onClick={() => setCurrentPage((prev) => Math.max(prev - 1, 1))}
                disabled={currentPage === 1}
              >
                Previous
              </Button>

              {Array.from({ length: Math.min(5, totalPages) }, (_, i) => {
                const pageNum = i + 1;
                return (
                  <Button
                    key={pageNum}
                    variant={currentPage === pageNum ? 'default' : 'outline'}
                    size="sm"
                    onClick={() => setCurrentPage(pageNum)}
                  >
                    {pageNum}
                  </Button>
                );
              })}

              {totalPages > 5 && (
                <>
                  <span className="px-2">...</span>
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={() => setCurrentPage(totalPages)}
                  >
                    {totalPages}
                  </Button>
                </>
              )}

              <Button
                variant="outline"
                size="sm"
                onClick={() =>
                  setCurrentPage((prev) => Math.min(prev + 1, totalPages))
                }
                disabled={currentPage === totalPages}
              >
                Next
              </Button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default ProductsPage;
